export type { FeticheTaste, FeticheMoodKey };

const STAT_KEYS = ['hp', 'attack', 'spattack', 'defense', 'spdefense', 'speed'] as const;
type StatKey = (typeof STAT_KEYS)[number];

const TASTE_RANK: Record<FeticheTaste, number> = {
    hated: 0,
    disliked: 1,
    neutral: 2,
    liked: 3,
    loved: 4,
};

export interface FeticheMoodSnapshot {
    moodKey: FeticheMoodKey;
    moodUntil: number;
    countdownMs: number;
    cravingBerryKeys: string[];
    dislikedBerryKeys: string[];
    lovedNow: string[];
    hatedNow: string[];
}

export interface FeticheFeedResult {
    ok: boolean;
    reason?: 'no_species' | 'satiety_full' | 'stomach_cramp' | 'unknown_berry';
    taste?: FeticheTaste;
    leveledUp?: boolean;
    evolved?: boolean;
    moodRotated?: boolean;
}

export interface ChooseFeticheResult {
    ok: boolean;
    reason?: 'already_chosen' | 'not_caught' | 'invalid_species' | 'not_base_species' | 'legendary_not_allowed';
}

function emptyStats(): PlayerMainStats {
    return { hp: 0, attack: 0, spattack: 0, defense: 0, spdefense: 0, speed: 0 };
}

function baseStatsFromSpecies(speciesKey: string, level: number): PlayerMainStats {
    const raw = getPokemonBaseStats(speciesKey, level);
    return {
        hp: Math.max(0, Math.floor(Number(raw.hp) || 0)),
        attack: Math.max(0, Math.floor(Number(raw.attack) || 0)),
        spattack: Math.max(0, Math.floor(Number(raw.spattack) || 0)),
        defense: Math.max(0, Math.floor(Number(raw.defense) || 0)),
        spdefense: Math.max(0, Math.floor(Number(raw.spdefense) || 0)),
        speed: Math.max(0, Math.floor(Number(raw.speed) || 0)),
    };
}

/** Base stats for a species at a given level (UI preview / snapshot). */
export function getFeticheBaseStatsAtLevel(speciesKey: string, level: number): PlayerMainStats {
    return baseStatsFromSpecies(speciesKey, level);
}

export function hashFeticheSeed(speciesKey: string, chosenAt: number): number {
    let h = 2166136261;
    const s = `${speciesKey}:${chosenAt}`;
    for (let i = 0; i < s.length; i++) {
        h ^= s.charCodeAt(i);
        h = Math.imul(h, 16777619);
    }
    return h >>> 0;
}

export function seededRng(seed: number): () => number {
    let s = seed >>> 0;
    return () => {
        s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
        return s / 0x100000000;
    };
}

export function createDefaultFeticheState(now = Date.now()): FeticheState {
    return {
        speciesKey: null,
        level: 1,
        xp: 0,
        stats: emptyStats(),
        satiety: FETICHE.satietyMax,
        lastTickAt: now,
        stomachCrampUntil: 0,
        tasteSeed: 0,
        tasteMoodIndex: 0,
        tasteMoodUntil: 0,
        personalCravingBerryKeys: [],
        moodDislikedBerryKeys: [],
        moodChangedPending: false,
    };
}

export function normalizeFeticheState(
    state: FeticheState | null | undefined,
    now = Date.now(),
): FeticheState {
    const base = state && typeof state === 'object' ? state : createDefaultFeticheState(now);
    const out: FeticheState = {
        speciesKey: typeof base.speciesKey === 'string' && base.speciesKey ? base.speciesKey : null,
        displaySpeciesKey: typeof base.displaySpeciesKey === 'string' && base.displaySpeciesKey
            ? base.displaySpeciesKey
            : null,
        level: Math.max(1, Math.min(FETICHE.maxLevel, Math.floor(Number(base.level) || 1))),
        xp: Math.max(0, Math.floor(Number(base.xp) || 0)),
        stats: { ...emptyStats(), ...(base.stats && typeof base.stats === 'object' ? base.stats : {}) },
        satiety: Math.max(0, Math.min(FETICHE.satietyMax, Number(base.satiety) || 0)),
        lastTickAt: Math.max(0, Number(base.lastTickAt) || now),
        stomachCrampUntil: Math.max(0, Number(base.stomachCrampUntil) || 0),
        chosenAt: base.chosenAt != null ? Math.max(0, Number(base.chosenAt) || 0) : undefined,
        tasteSeed: Math.max(0, Math.floor(Number(base.tasteSeed) || 0)),
        tasteMoodIndex: Math.max(0, Math.floor(Number(base.tasteMoodIndex) || 0)),
        tasteMoodUntil: Math.max(0, Number(base.tasteMoodUntil) || 0),
        personalCravingBerryKeys: filterBerryKeys(base.personalCravingBerryKeys),
        moodDislikedBerryKeys: filterBerryKeys(base.moodDislikedBerryKeys),
        moodChangedPending: !!base.moodChangedPending,
        feticheOnboardingSeen: !!base.feticheOnboardingSeen,
    };
    for (const key of STAT_KEYS) {
        out.stats[key] = Math.max(0, Math.floor(Number(out.stats[key]) || 0));
    }
    if (out.speciesKey && out.stats.hp === 0 && out.stats.attack === 0) {
        out.stats = baseStatsFromSpecies(getFeticheDisplaySpecies(out), out.level);
    }
    if (out.speciesKey && out.chosenAt == null) {
        out.chosenAt = out.lastTickAt || now;
    }
    if (out.speciesKey) {
        syncFeticheDisplaySpecies(out);
        syncFeticheStatsFromLevel(out);
    }
    return out;
}

function getLevelEvolutionStep(speciesKey: string): { level: number; evolvesTo: string } | null {
    const def = EVOLUTIONS[speciesKey];
    if (!def) return null;
    if (Array.isArray(def.options) && def.options.length > 0) {
        for (const opt of def.options) {
            const lv = Number(opt.level);
            if (Number.isFinite(lv) && lv > 0 && typeof opt.evolves_to === 'string' && opt.evolves_to) {
                return { level: Math.floor(lv), evolvesTo: opt.evolves_to };
            }
        }
        return null;
    }
    const lv = Number(def.level);
    if (Number.isFinite(lv) && lv > 0 && typeof def.evolves_to === 'string' && def.evolves_to) {
        return { level: Math.floor(lv), evolvesTo: def.evolves_to };
    }
    return null;
}

/** Resolved display species for fétiche level (level-based evolutions only). */
export function resolveFeticheDisplaySpecies(baseSpeciesKey: string, level: number): string {
    const base = String(baseSpeciesKey || '').trim();
    if (!base) return '';
    let current = base;
    const lv = Math.max(1, Math.floor(Number(level) || 1));
    for (;;) {
        const step = getLevelEvolutionStep(current);
        if (!step || lv < step.level) break;
        current = step.evolvesTo;
    }
    return current;
}

export function getFeticheDisplaySpecies(state: FeticheState): string {
    if (!state.speciesKey) return '';
    return resolveFeticheDisplaySpecies(state.speciesKey, state.level);
}

export function syncFeticheDisplaySpecies(state: FeticheState): string {
    if (!state.speciesKey) {
        state.displaySpeciesKey = null;
        return '';
    }
    const display = resolveFeticheDisplaySpecies(state.speciesKey, state.level);
    state.displaySpeciesKey = display;
    return display;
}

export function getNextFeticheEvolutionInfo(
    baseSpeciesKey: string,
    level: number,
): { atLevel: number; speciesKey: string } | null {
    const display = resolveFeticheDisplaySpecies(baseSpeciesKey, level);
    const step = getLevelEvolutionStep(display);
    if (!step) return null;
    const lv = Math.max(1, Math.floor(Number(level) || 1));
    if (lv >= step.level) return null;
    return { atLevel: step.level, speciesKey: step.evolvesTo };
}

function displaySpeciesAtLevel(state: FeticheState, level: number): string {
    if (!state.speciesKey) return '';
    return resolveFeticheDisplaySpecies(state.speciesKey, level);
}

function filterBerryKeys(keys: unknown): string[] {
    if (!isUnknownArray(keys)) return [];
    const allowed = new Set<string>(BERRY_DEX_KEYS);
    const out: string[] = [];
    for (const key of keys) {
        if (typeof key === 'string' && allowed.has(key)) out.push(key);
    }
    return out;
}

export function getEvolutionFamilyRoot(speciesKey: string): string {
    const name = String(speciesKey || '').trim();
    if (!name) return name;
    const families = EVOLUTION_FAMILIES as Record<string, string>;
    return families[name] ?? name;
}

/** True when the species is the root of its evolution line (lvl-1 fétiche pick). */
export function isFeticheBaseSpecies(speciesKey: string): boolean {
    const name = String(speciesKey || '').trim();
    if (!name) return false;
    return getEvolutionFamilyRoot(name) === name;
}

function getNationalDexNumber(speciesKey: string): number {
    const id = Number((POKEMON_SPRITE_IDS as Record<string, number>)[speciesKey] || 0);
    return id > 0 ? id : Number.MAX_SAFE_INTEGER;
}

/** Base species eligible for fétiche pick (no legendaries). */
export function isFeticheEligibleSpecies(speciesKey: string): boolean {
    const name = String(speciesKey || '').trim();
    if (!name || !isFeticheBaseSpecies(name)) return false;
    return speciesNaturalRarity(name) !== RARITY.LEGENDARY;
}

export function getCaughtSpeciesKeys(pokedex: Record<string, PokedexEntry>): string[] {
    const seen = new Set<string>();
    const out: string[] = [];
    for (const entry of Object.values(pokedex)) {
        if (!entry?.caught) continue;
        const name = typeof entry.name === 'string' ? entry.name.trim() : '';
        if (!name || seen.has(name)) continue;
        seen.add(name);
        out.push(name);
    }
    return out.sort((a, b) => a.localeCompare(b));
}

/** Caught species mapped to their evolution-line root (one entry per family). */
export function getCaughtFeticheBaseSpeciesKeys(pokedex: Record<string, PokedexEntry>): string[] {
    const roots = new Set<string>();
    for (const name of getCaughtSpeciesKeys(pokedex)) {
        roots.add(getEvolutionFamilyRoot(name));
    }
    return [...roots]
        .filter(isFeticheEligibleSpecies)
        .sort((a, b) => getNationalDexNumber(a) - getNationalDexNumber(b) || a.localeCompare(b));
}

export function isSpeciesCaughtInFamily(speciesKey: string, pokedex: Record<string, PokedexEntry>): boolean {
    const root = getEvolutionFamilyRoot(speciesKey);
    return getCaughtSpeciesKeys(pokedex).some((name) => getEvolutionFamilyRoot(name) === root);
}

export function isSpeciesCaught(speciesKey: string, pokedex: Record<string, PokedexEntry>): boolean {
    return getCaughtSpeciesKeys(pokedex).includes(speciesKey);
}

export function getSpeciesElementTypes(speciesKey: string): string[] {
    const primary = POKEMON_PRIMARY_TYPES[speciesKey] ?? inferPrimaryTypeFromPool(speciesKey);
    const secondary = POKEMON_SECONDARY_TYPES[speciesKey];
    const types: string[] = [];
    if (primary) types.push(primary);
    if (secondary && secondary !== primary) types.push(secondary);
    return types;
}

function inferPrimaryTypeFromPool(speciesName: string): string | null {
    const poolObj = POKEMON_POOL;
    const rarities = [RARITY.LEGENDARY, RARITY.EPIC, RARITY.RARE, RARITY.COMMON];
    for (const rarity of rarities) {
        const pool = poolObj[rarity];
        if (!pool) continue;
        for (const typeKey in pool) {
            if (pool[typeKey]?.includes(speciesName)) return typeKey;
        }
    }
    return null;
}

function pickUniqueBerries(rng: () => number, count: number, exclude: Set<string>): string[] {
    const pool = BERRY_DEX_KEYS.filter((k) => !exclude.has(k));
    const out: string[] = [];
    const used = new Set(exclude);
    for (let i = 0; i < count && pool.length > 0; i++) {
        const idx = Math.floor(rng() * pool.length);
        const key = pool.splice(idx, 1)[0]!;
        out.push(key);
        used.add(key);
    }
    return out;
}

export function getPersonalTasteBerries(tasteSeed: number): { loved: string[]; hated: string[] } {
    const rng = seededRng(tasteSeed);
    const total = FETICHE.personalTasteBerryCount;
    const lovedCount = Math.ceil(total / 2);
    const hatedCount = Math.floor(total / 2);
    const loved = pickUniqueBerries(rng, lovedCount, new Set());
    const hated = pickUniqueBerries(rng, hatedCount, new Set(loved));
    return { loved, hated };
}

function mergeTaste(a: FeticheTaste, b: FeticheTaste): FeticheTaste {
    return TASTE_RANK[a] >= TASTE_RANK[b] ? a : b;
}

function mergeTasteWorst(a: FeticheTaste, b: FeticheTaste): FeticheTaste {
    return TASTE_RANK[a] <= TASTE_RANK[b] ? a : b;
}

function typeBaseTaste(speciesTypes: string[], berryKey: string): FeticheTaste {
    let taste: FeticheTaste = 'neutral';
    const tier = getBerryProductionTier(berryKey);
    for (const type of speciesTypes) {
        const preferred = FETICHE_TYPE_PREFERRED_BERRIES[type] ?? [];
        if (preferred.includes(berryKey)) {
            taste = mergeTaste(taste, preferred.indexOf(berryKey) < 2 ? 'loved' : 'liked');
        }
        const dislikedTiers = FETICHE_TYPE_DISLIKED_TIERS[type] ?? [];
        if (dislikedTiers.includes(tier)) {
            taste = mergeTasteWorst(taste, 'disliked');
        }
    }
    return taste;
}

export function resolveBerryTaste(
    state: FeticheState,
    speciesTypes: string[],
    berryKey: string,
    _now = Date.now(),
): FeticheTaste {
    if (!BERRY_DEX_KEYS.includes(berryKey as typeof BERRY_DEX_KEYS[number])) {
        return 'neutral';
    }
    let taste = typeBaseTaste(speciesTypes, berryKey);

    if (state.tasteSeed > 0) {
        const personal = getPersonalTasteBerries(state.tasteSeed);
        if (personal.hated.includes(berryKey)) taste = 'hated';
        else if (personal.loved.includes(berryKey)) taste = mergeTaste(taste, 'loved');
    }

    if (state.personalCravingBerryKeys.includes(berryKey)) {
        taste = mergeTaste(taste, 'loved');
    }
    if (state.moodDislikedBerryKeys.includes(berryKey)) {
        taste = mergeTasteWorst(taste, 'disliked');
    }

    return taste;
}

export function rotateFeticheMood(
    state: FeticheState,
    speciesTypes: string[],
    now: number,
    rng: () => number = Math.random,
): void {
    state.tasteMoodIndex = Math.max(0, Math.floor(Number(state.tasteMoodIndex) || 0)) + 1;
    state.tasteMoodUntil = now + FETICHE.moodRotationMs;

    const preferredPool = new Set<string>();
    for (const type of speciesTypes) {
        for (const key of FETICHE_TYPE_PREFERRED_BERRIES[type] ?? []) {
            preferredPool.add(key);
        }
    }
    const pool = preferredPool.size > 0
        ? [...preferredPool]
        : [...BERRY_DEX_KEYS];
    const craving: string[] = [];
    const used = new Set<string>();
    const cravingCount = Math.min(FETICHE.cravingBerryCount, pool.length);
    for (let i = 0; i < cravingCount; i++) {
        const idx = Math.floor(rng() * pool.length);
        const key = pool[idx]!;
        if (!used.has(key)) {
            craving.push(key);
            used.add(key);
        }
        pool.splice(idx, 1);
        if (pool.length === 0) break;
    }
    state.personalCravingBerryKeys = craving;
    state.moodDislikedBerryKeys = pickUniqueBerries(
        rng,
        FETICHE.moodDislikeBerryCount,
        used,
    );
    state.moodChangedPending = true;
}

export function ensureFeticheMoodScheduled(
    state: FeticheState,
    speciesTypes: string[],
    now: number,
    rng: () => number = Math.random,
): boolean {
    if (!state.speciesKey) return false;
    if (state.tasteMoodUntil <= 0) {
        rotateFeticheMood(state, speciesTypes, now, rng);
        return true;
    }
    if (now >= state.tasteMoodUntil) {
        rotateFeticheMood(state, speciesTypes, now, rng);
        return true;
    }
    return false;
}

export function getFeticheMoodSnapshot(
    state: FeticheState,
    speciesTypes: string[],
    now: number,
): FeticheMoodSnapshot | null {
    if (!state.speciesKey) return null;
    const lovedNow: string[] = [];
    const hatedNow: string[] = [];
    for (const key of BERRY_DEX_KEYS) {
        const taste = resolveBerryTaste(state, speciesTypes, key, now);
        if (taste === 'loved') lovedNow.push(key);
        else if (taste === 'hated') hatedNow.push(key);
    }
    return {
        moodKey: getFeticheMoodKey(state.tasteMoodIndex),
        moodUntil: state.tasteMoodUntil,
        countdownMs: Math.max(0, state.tasteMoodUntil - now),
        cravingBerryKeys: [...state.personalCravingBerryKeys],
        dislikedBerryKeys: [...state.moodDislikedBerryKeys],
        lovedNow: lovedNow.slice(0, 5),
        hatedNow: hatedNow.slice(0, 5),
    };
}

export function buildFeticheTasteBoard(
    state: FeticheState,
    speciesTypes: string[],
    now: number,
): Record<string, FeticheTaste> {
    const board: Record<string, FeticheTaste> = {};
    for (const key of BERRY_DEX_KEYS) {
        board[key] = resolveBerryTaste(state, speciesTypes, key, now);
    }
    return board;
}

export function getFeticheSatietyFeedRoom(satiety: number, taste: FeticheTaste): number {
    const floor = Math.floor(Number(satiety) || 0);
    return FETICHE.satietyMax - floor - FETICHE_TASTE_EFFECTS[taste].satietyGain;
}

export function canFeedFeticheBerry(
    state: FeticheState,
    berryKey: string,
    speciesTypes: string[],
    now: number,
): boolean {
    if (!state.speciesKey) return false;
    if ((Number(state.stomachCrampUntil) || 0) > now) return false;
    if (!BERRY_DEX_KEYS.includes(berryKey as typeof BERRY_DEX_KEYS[number])) return false;
    const taste = resolveBerryTaste(state, speciesTypes, berryKey, now);
    return getFeticheSatietyFeedRoom(state.satiety, taste) >= 0;
}

export function canFeedAnyFeticheBerry(
    state: FeticheState,
    speciesTypes: string[],
    ownedBerryKeys: string[],
    now: number,
): boolean {
    if (!state.speciesKey) return false;
    if ((Number(state.stomachCrampUntil) || 0) > now) return false;
    return ownedBerryKeys.some((key) => canFeedFeticheBerry(state, key, speciesTypes, now));
}

/** True when at least one owned berry can be fed without exceeding satiety max. */
export function isFeticheHungry(
    state: FeticheState,
    speciesTypes?: string[],
    ownedBerryKeys?: string[],
    now = Date.now(),
): boolean {
    if (!state.speciesKey) return false;
    if ((Number(state.stomachCrampUntil) || 0) > now) return false;
    if (speciesTypes && ownedBerryKeys) {
        return canFeedAnyFeticheBerry(state, speciesTypes, ownedBerryKeys, now);
    }
    return getFeticheSatietyFeedRoom(state.satiety, 'loved') >= 0;
}

function applySatietyDecay(state: FeticheState, elapsedMs: number): void {
    if (elapsedMs <= 0) return;
    const hours = elapsedMs / (60 * 60 * 1000);
    const decay = hours * FETICHE.satietyDecayPerHour;
    state.satiety = Math.max(0, (Number(state.satiety) || 0) - decay);
}

function applyPassiveGrowth(state: FeticheState, elapsedSec: number): boolean {
    if (!state.speciesKey || elapsedSec <= 0) return false;
    let evolved = false;
    const displayBefore = getFeticheDisplaySpecies(state);
    if (state.level < FETICHE.maxLevel) {
        state.xp += FETICHE.passiveXpPerSec * elapsedSec;
        while (state.level < FETICHE.maxLevel && state.xp >= getFeticheXpToNextLevel(state.level)) {
            state.xp -= getFeticheXpToNextLevel(state.level);
            const prevLevel = state.level;
            state.level += 1;
            recalcFeticheStatsFromLevel(state, prevLevel);
            if (getFeticheDisplaySpecies(state) !== displayBefore) {
                evolved = true;
            }
        }
    }
    return evolved;
}

/** Ensures stats are at least the base values for the current level (preserves berry bonuses above). */
export function syncFeticheStatsFromLevel(state: FeticheState): void {
    if (!state.speciesKey) return;
    recalcFeticheStatsFromLevel(state);
}

export function recalcFeticheStatsFromLevel(state: FeticheState, previousLevel?: number): void {
    if (!state.speciesKey) return;
    syncFeticheDisplaySpecies(state);
    const display = getFeticheDisplaySpecies(state);
    const base = baseStatsFromSpecies(display, state.level);
    const oldBase = previousLevel != null && previousLevel < state.level
        ? baseStatsFromSpecies(displaySpeciesAtLevel(state, previousLevel), previousLevel)
        : null;
    for (const key of STAT_KEYS) {
        const floor = Number(base[key]) || 0;
        const current = Number(state.stats[key]) || 0;
        if (oldBase) {
            const oldFloor = Number(oldBase[key]) || 0;
            const bonus = Math.max(0, current - oldFloor);
            state.stats[key] = floor + bonus;
        } else if (current < floor) {
            state.stats[key] = floor;
        }
    }
}

export interface FeticheTickResult {
    moodRotated: boolean;
    evolved: boolean;
    elapsedMs: number;
}

export function tickFeticheState(
    state: FeticheState,
    now: number,
    rng: () => number = Math.random,
): FeticheTickResult {
    normalizeFeticheState(state, now);
    if (!state.speciesKey) {
        state.lastTickAt = now;
        return { moodRotated: false, evolved: false, elapsedMs: 0 };
    }

    const last = Number(state.lastTickAt) || now;
    let elapsedMs = Math.max(0, now - last);
    elapsedMs = Math.min(elapsedMs, FETICHE.offlineCapMs);
    state.lastTickAt = now;

    if (elapsedMs <= 0) {
        return { moodRotated: false, evolved: false, elapsedMs: 0 };
    }

    const speciesTypes = getSpeciesElementTypes(state.speciesKey);
    let moodRotated = false;
    const moodBefore = state.tasteMoodIndex;
    while (now >= state.tasteMoodUntil && state.tasteMoodUntil > 0) {
        rotateFeticheMood(state, speciesTypes, state.tasteMoodUntil, seededRng(state.tasteSeed + state.tasteMoodIndex));
    }
    if (state.tasteMoodUntil <= 0) {
        rotateFeticheMood(state, speciesTypes, now, rng);
        moodRotated = true;
    }
    if (state.tasteMoodIndex !== moodBefore) moodRotated = true;

    applySatietyDecay(state, elapsedMs);
    const evolved = applyPassiveGrowth(state, elapsedMs / 1000);

    return { moodRotated, evolved, elapsedMs };
}

/** Seconds since fétiche was chosen; min 1. Never resets on level-up. */
export function getFeticheTransmissionSeconds(state: FeticheState | null | undefined, now = Date.now()): number {
    if (!state?.speciesKey) return 0;
    const s = normalizeFeticheState(state, now);
    const chosenAt = s.chosenAt != null
        ? Math.max(0, Number(s.chosenAt) || 0)
        : Math.max(0, Number(s.lastTickAt) || now);
    return Math.max(1, Math.floor((now - chosenAt) / 1000));
}

function feticheGainPerSecForStat(statValue: number, transmissionSec: number): number {
    const stat = Math.floor(Number(statValue) || 0);
    if (stat <= 0 || transmissionSec <= 0) return 0;
    return Math.floor(stat * transmissionSec * FETICHE.gainsRate);
}

export function getFeticheStatsForGains(
    state: FeticheState | null | undefined,
    now = Date.now(),
): PlayerMainStats {
    const empty = emptyStats();
    if (!state?.speciesKey) return empty;
    const s = normalizeFeticheState(state, now);
    const transmissionSec = getFeticheTransmissionSeconds(s, now);
    return {
        hp: feticheGainPerSecForStat(s.stats.hp, transmissionSec),
        attack: feticheGainPerSecForStat(s.stats.attack, transmissionSec),
        spattack: feticheGainPerSecForStat(s.stats.spattack, transmissionSec),
        defense: feticheGainPerSecForStat(s.stats.defense, transmissionSec),
        spdefense: feticheGainPerSecForStat(s.stats.spdefense, transmissionSec),
        speed: feticheGainPerSecForStat(s.stats.speed, transmissionSec),
    };
}

/** Total main-stat gain for one stat over tickCount seconds starting at startTransmissionSec. */
export function computeFetichePassiveGainForStat(
    statValue: number,
    startTransmissionSec: number,
    tickCount: number,
): number {
    const perSecBase = Math.floor((Number(statValue) || 0) * FETICHE.gainsRate);
    if (perSecBase <= 0 || tickCount <= 0 || startTransmissionSec <= 0) return 0;
    const n = tickCount;
    const s = startTransmissionSec;
    return Math.floor(perSecBase * n * (2 * s + n - 1) / 2);
}

/** Applies compounded fétiche passive gains for a batch interval. */
export function applyFetichePassiveGainBatch(
    feticheStats: PlayerMainStats,
    startTransmissionSec: number,
    tickCount: number,
    target: PlayerMainStats,
): void {
    if (tickCount <= 0 || startTransmissionSec <= 0) return;
    for (const key of STAT_KEYS) {
        const added = computeFetichePassiveGainForStat(feticheStats[key], startTransmissionSec, tickCount);
        if (added > 0) {
            target[key] = (Number(target[key]) || 0) + added;
        }
    }
}

export function computeFeticheBerryStatGain(
    berryKey: string,
    taste: FeticheTaste,
): Partial<PlayerMainStats> {
    const base = getFeticheBerryStatEffect(berryKey);
    const mult = FETICHE_TASTE_EFFECTS[taste].statEffMult;
    return scaleFeticheBerryStatEffect(base, mult);
}

export function chooseFeticheSpecies(
    state: FeticheState,
    speciesKey: string,
    pokedex: Record<string, PokedexEntry>,
    now = Date.now(),
): ChooseFeticheResult {
    normalizeFeticheState(state, now);
    if (state.speciesKey) return { ok: false, reason: 'already_chosen' };
    const name = String(speciesKey || '').trim();
    if (!name || !isKnownSpecies(name)) return { ok: false, reason: 'invalid_species' };
    if (!isFeticheBaseSpecies(name)) return { ok: false, reason: 'not_base_species' };
    if (speciesNaturalRarity(name) === RARITY.LEGENDARY) return { ok: false, reason: 'legendary_not_allowed' };
    if (!isSpeciesCaughtInFamily(name, pokedex)) return { ok: false, reason: 'not_caught' };

    state.speciesKey = name;
    state.displaySpeciesKey = name;
    state.level = 1;
    state.xp = 0;
    state.stats = baseStatsFromSpecies(name, 1);
    state.satiety = FETICHE.satietyMax;
    state.chosenAt = now;
    state.tasteSeed = hashFeticheSeed(name, now);
    state.tasteMoodIndex = 0;
    state.tasteMoodUntil = 0;
    state.personalCravingBerryKeys = [];
    state.moodDislikedBerryKeys = [];
    state.moodChangedPending = false;
    state.stomachCrampUntil = 0;
    state.lastTickAt = now;

    const speciesTypes = getSpeciesElementTypes(name);
    rotateFeticheMood(state, speciesTypes, now, seededRng(state.tasteSeed));

    return { ok: true };
}

export function feedFeticheBerry(
    state: FeticheState,
    berryKey: string,
    speciesTypes: string[],
    now: number,
): FeticheFeedResult {
    normalizeFeticheState(state, now);
    if (!state.speciesKey) return { ok: false, reason: 'no_species' };
    if (!BERRY_DEX_KEYS.includes(berryKey as typeof BERRY_DEX_KEYS[number])) {
        return { ok: false, reason: 'unknown_berry' };
    }
    if (!canFeedFeticheBerry(state, berryKey, speciesTypes, now)) {
        if ((Number(state.stomachCrampUntil) || 0) > now) {
            return { ok: false, reason: 'stomach_cramp' };
        }
        return { ok: false, reason: 'satiety_full' };
    }

    const taste = resolveBerryTaste(state, speciesTypes, berryKey, now);
    const effect = FETICHE_TASTE_EFFECTS[taste];

    state.satiety = Math.min(
        FETICHE.satietyMax,
        (Number(state.satiety) || 0) + effect.satietyGain,
    );

    if (effect.stomachCramp) {
        state.stomachCrampUntil = now + FETICHE.stomachCrampMs;
    }

    let leveledUp = false;
    let evolved = false;
    const displayBefore = getFeticheDisplaySpecies(state);
    if (effect.xpMult > 0 && state.level < FETICHE.maxLevel) {
        const xpGain = Math.floor(15 * effect.xpMult);
        state.xp += xpGain;
        while (state.level < FETICHE.maxLevel && state.xp >= getFeticheXpToNextLevel(state.level)) {
            state.xp -= getFeticheXpToNextLevel(state.level);
            const prevLevel = state.level;
            state.level += 1;
            leveledUp = true;
            recalcFeticheStatsFromLevel(state, prevLevel);
            if (getFeticheDisplaySpecies(state) !== displayBefore) {
                evolved = true;
            }
        }
    }

    const boost = computeFeticheBerryStatGain(berryKey, taste);
    for (const key of STAT_KEYS) {
        const add = Number(boost[key]) || 0;
        if (add > 0) state.stats[key] = (Number(state.stats[key]) || 0) + add;
    }

    return { ok: true, taste, leveledUp, evolved };
}

export type QaSetFeticheLevelFailReason = 'no_fetiche' | 'no_species' | 'invalid_level' | 'invalid_xp_pct';

export interface QaSetFeticheLevelResult {
    ok: boolean;
    level?: number;
    xp?: number;
    xpToNext?: number;
    xpPct?: number;
    displaySpeciesKey?: string | null;
    nextEvolutionAtLevel?: number | null;
    reason?: QaSetFeticheLevelFailReason;
}

export function setFeticheLevelForQa(
    game: import('../types/game.js').GameRuntime,
    level: number = 29,
    xpPct: number = 0.99,
    options?: { notify?: boolean },
): QaSetFeticheLevelResult {
    if (!game.unlockedFeatures?.fetiche) {
        return { ok: false, reason: 'no_fetiche' };
    }

    const state = normalizeFeticheState(
        game.feticheState ?? createDefaultFeticheState(Date.now()),
        Date.now(),
    );
    if (!state.speciesKey) {
        return { ok: false, reason: 'no_species' };
    }

    const pct = Number(xpPct);
    if (!Number.isFinite(pct) || pct < 0 || pct > 1) {
        return { ok: false, reason: 'invalid_xp_pct' };
    }

    const lv = Math.floor(Number(level) || 0);
    if (!Number.isFinite(lv) || lv < 1 || lv > FETICHE.maxLevel) {
        return { ok: false, reason: 'invalid_level' };
    }

    const xpToNext = lv >= FETICHE.maxLevel ? 0 : getFeticheXpToNextLevel(lv);
    const xp = lv >= FETICHE.maxLevel
        ? 0
        : Math.min(xpToNext - 1, Math.max(0, Math.floor(xpToNext * pct)));

    state.level = lv;
    state.xp = xp;
    syncFeticheStatsFromLevel(state);
    game.feticheState = state;

    if (options?.notify !== false) {
        void import('./feticheSnapshot.ts').then((m) => m.notifyFeticheChanged(game, { force: true }));
    }

    const nextEvolution = getNextFeticheEvolutionInfo(state.speciesKey, lv);
    return {
        ok: true,
        level: lv,
        xp,
        xpToNext,
        xpPct: pct,
        displaySpeciesKey: state.displaySpeciesKey ?? null,
        nextEvolutionAtLevel: nextEvolution?.atLevel ?? null,
    };
}
